/* Enforce hidden attribute */
[hidden] {
  display: none !important;
}

:root {
  --bg-primary: #0f172a;
  --card-bg: #1e293b;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --border-color: #334155;
  --border-focus: #38bdf8;
  --error-color: #f87171;
  --shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.4), 0 8px 10px -6px rgba(0, 0, 0, 0.4);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background-color: var(--bg-primary);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
}

.converter-card {
  background-color: var(--card-bg);
  width: 100%;
  max-width: 440px;
  border-radius: 1rem;
  border: 1px solid var(--border-color);
  padding: 2rem;
  box-shadow: var(--shadow);
}

.card-header {
  text-align: center;
  margin-bottom: 1.75rem;
}

.title {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
  margin-bottom: 0.35rem;
}

.subtitle {
  font-size: 0.875rem;
  color: var(--text-muted);
}

.preview-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  margin-bottom: 2rem;
}

.color-swatch {
  width: 100%;
  height: 120px;
  border-radius: 0.75rem;
  border: 2px solid var(--border-color);
  background-color: #ff8800;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.2);
  transition: background-color 0.15s ease, border-color 0.15s ease;
}

.color-swatch.swatch-invalid {
  background-color: #272f3d !important;
  border-color: var(--error-color);
  background-image: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 10px,
    rgba(248, 113, 113, 0.15) 10px,
    rgba(248, 113, 113, 0.15) 20px
  );
}

.output-box {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
}

.output-label {
  font-size: 0.75rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: var(--text-muted);
}

.hex-text {
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: var(--text-main);
}

.hex-text.error-text {
  color: var(--error-color);
  font-size: 1.35rem;
  letter-spacing: normal;
}

.inputs-form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.input-group {
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
}

.input-group label {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-main);
}

.input-group input[type="number"] {
  appearance: textfield;
  -moz-appearance: textfield;
  width: 100%;
  padding: 0.75rem 1rem;
  font-size: 1.1rem;
  font-weight: 500;
  background-color: #0f172a;
  color: var(--text-main);
  border: 1.5px solid var(--border-color);
  border-radius: 0.5rem;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.input-group input[type="number"]::-webkit-outer-spin-button,
.input-group input[type="number"]::-webkit-inner-spin-button {
  -webkit-appearance: none;
  margin: 0;
}

.input-group input[type="number"]:hover {
  border-color: #475569;
}

.input-group input[type="number"]:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(56, 189, 248, 0.25);
}

.input-group input[type="number"].input-invalid {
  border-color: var(--error-color);
}

.input-group input[type="number"].input-invalid:focus {
  box-shadow: 0 0 0 3px rgba(248, 113, 113, 0.25);
}

.error-message {
  font-size: 0.85rem;
  font-weight: 500;
  color: var(--error-color);
}

@media (max-width: 360px) {
  .converter-card {
    padding: 1.25rem;
  }
  .title {
    font-size: 1.25rem;
  }
  .hex-text {
    font-size: 1.5rem;
  }
}

document.addEventListener('DOMContentLoaded', () => {
  const redInput = document.getElementById('redInput');
  const greenInput = document.getElementById('greenInput');
  const blueInput = document.getElementById('blueInput');

  const errorRed = document.getElementById('errorRed');
  const errorGreen = document.getElementById('errorGreen');
  const errorBlue = document.getElementById('errorBlue');

  const swatch = document.getElementById('colorSwatch');
  const hexOutput = document.getElementById('hexValue');

  function validateChannel(inputElem, errorElem) {
    const val = inputElem.value.trim();

    if (val === '' || isNaN(val)) {
      showError(inputElem, errorElem);
      return null;
    }

    const num = Number(val);
    if (!Number.isInteger(num) || num < 0 || num > 255) {
      showError(inputElem, errorElem);
      return null;
    }

    hideError(inputElem, errorElem);
    return num;
  }

  function showError(inputElem, errorElem) {
    inputElem.classList.add('input-invalid');
    inputElem.setAttribute('aria-invalid', 'true');
    errorElem.removeAttribute('hidden');
  }

  function hideError(inputElem, errorElem) {
    inputElem.classList.remove('input-invalid');
    inputElem.removeAttribute('aria-invalid');
    errorElem.setAttribute('hidden', '');
  }

  function toHexComponent(num) {
    return num.toString(16).padStart(2, '0').toUpperCase();
  }

  function updateColor() {
    const r = validateChannel(redInput, errorRed);
    const g = validateChannel(greenInput, errorGreen);
    const b = validateChannel(blueInput, errorBlue);

    if (r === null || g === null || b === null) {
      hexOutput.textContent = 'Invalid value';
      hexOutput.classList.add('error-text');
      swatch.classList.add('swatch-invalid');
      swatch.style.backgroundColor = '';
      return;
    }

    const hexCode = `#${toHexComponent(r)}${toHexComponent(g)}${toHexComponent(b)}`;
    hexOutput.textContent = hexCode;
    hexOutput.classList.remove('error-text');
    swatch.classList.remove('swatch-invalid');
    swatch.style.backgroundColor = hexCode;
  }

  [redInput, greenInput, blueInput].forEach(input => {
    input.addEventListener('input', updateColor);
    input.addEventListener('change', updateColor);
  });

  updateColor();
});
